function validate([left, right]) {
  for (const [name, value] of [['left', left], ['right', right]]) {
    if (typeof value !== 'string' || !/^[1-9][0-9]{0,17}$/.test(value)) return `${name} must be a positive integer of 1 to 18 digits without leading zeros.`;
  }
  if (BigInt(left) > BigInt(right)) return 'left must not be greater than right.';
  return null;
}

