function superpalindromesInRange(left, right) {
  const low = BigInt(left);
  const high = BigInt(right);
  const reverse = text => [...text].reverse().join('');
  let count = 0;

  for (const skip of [1, 0]) {
    for (let half = 1; half < 100000; half++) {
      const prefix = String(half);
      const root = prefix + reverse(prefix).slice(skip);
      const square = BigInt(root) * BigInt(root);
      if (square > high) break;
      const digits = square.toString();
      if (square >= low && digits === reverse(digits)) count++;
    }
  }
  return count;
}

