function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const digits = n => { let s = String(int(1, 9)); while (s.length < n) s += int(0, 9); return s; };
  if (size === 'large') {
    const low = rand() < 0.5 ? '1' : digits(int(1, 8));
    const high = rand() < 0.5 ? '999999999999999999' : digits(int(17, 18));
    return [low, high];
  }
  // Super-palindromes with small roots, so range ends can sit right next to answers.
  const special = [];
  for (let root = 1; root < 30000; root++) {
    const r = String(root), sq = String(root * root);
    if (r === [...r].reverse().join('') && sq === [...sq].reverse().join('')) special.push(BigInt(sq));
  }
  const pick = () => special[int(0, special.length - 1)];
  const mode = rand();
  let low, high;
  if (mode < 0.35) {
    const s = pick();
    low = s - BigInt(int(0, 2));
    high = s + BigInt(int(-1, 2));
  } else if (mode < 0.7) {
    let s = pick(), t = pick();
    if (s > t) [s, t] = [t, s];
    low = s + BigInt(int(-1, 1));
    high = t + BigInt(int(-1, 1));
  } else {
    low = BigInt(digits(int(1, 12)));
    high = BigInt(digits(int(1, 14)));
  }
  if (low < 1n) low = 1n;
  if (high < 1n) high = 1n;
  if (low > high) [low, high] = [high, low];
  return [String(low), String(high)];
}
